<template>
<sf-sheet :open="visible" :busy="app.busy" :contained="true" :resizable="false" content-class="mobile-sheet" label="Action confirmation" @close="$emit('close')">
  <template v-if="app.gate"><h2>{{ gateTitle }}</h2><p v-if="app.gate.reason==='CONSUMPTION_POLICY_UNDEFINED'">This action is not available yet. Your Credits have not been held or charged.</p><p v-else-if="app.gate.reason==='ENTITLEMENT_REQUIRED'">{{ app.gate.serviceName||app.displayContent.name }} requires access included in an eligible plan. Your basic data and saved conversations stay available.<span v-if="app.gate.extraPrice"> Extra use may cost {{ app.gate.extraPrice }} Credits after included usage.</span></p><p v-else-if="app.gate.reason==='INCLUDED_USAGE_EXHAUSTED'">Your included {{ app.gate.serviceName||'service' }} resets {{ app.shortDate(app.gate.resetAt) }}. Your saved results remain available.</p><p v-else-if="app.gate.reason==='CREDITS_INSUFFICIENT'">This action needs {{ app.gate.credits }} {{ creditTypeLabel(app.gate.creditType||'LEGACY_CREDIT') }}. Your balance is {{ app.gate.available===undefined?app.data.wallet.available:app.gate.available }}.</p><p v-else>{{ app.gate.message||'This service is unavailable right now. Please try again later.' }}</p><button v-if="['ENTITLEMENT_REQUIRED','CREDITS_INSUFFICIENT'].includes(app.gate.reason)" class="mobile-primary" @click="$emit('resolve')">{{ app.gate.reason==='ENTITLEMENT_REQUIRED'?'View plans':'Add Credits' }}</button><button class="mobile-secondary" @click="$emit('close')">{{ ['ENTITLEMENT_REQUIRED','CREDITS_INSUFFICIENT'].includes(app.gate.reason)?'Not now':'Close' }}</button></template>
  <template v-if="app.quote"><h2>{{ app.quote.action==='change_plan'?'Switch to '+app.quote.product.name:app.quote.product.name }}</h2><p class="sheet-price">{{ app.money(app.quote.sku.priceCents,app.quote.sku.currency) }}{{ app.quote.suit?(app.quote.sku.billingPeriod==='annual'?' / year':' / month'):'' }}</p><p v-if="app.quote.action==='change_plan'">Starts {{ app.shortDate(app.quote.startsAt) }}. No charge today; your current benefits remain until then.</p><p v-else-if="app.quote.suit">Starts {{ app.shortDate(app.quote.startsAt) }}. Renews {{ app.shortDate(app.quote.expiresAtMembership) }} until canceled.</p><p v-else>{{ app.quote.credits.amount }} {{ creditTypeLabel(app.quote.credits.creditType||'LEGACY_CREDIT') }} · {{ app.quote.credits.validityDays===null?'Never expire':'Valid '+app.quote.credits.validityDays+' days' }}. This does not change your membership.</p><div v-if="app.quote.suit" class="sheet-facts"><p v-for="rule in app.quote.suit.config.includedServices||[]" :key="rule.serviceId">{{ rule.amount }} {{ app.serviceLabel(rule.serviceId) }} / {{ rule.period==='weekly'?'week':'month' }}</p><p v-for="grant in app.quote.suit.config.creditGrants||[]" :key="grant.creditType">{{ creditGrantLabel(grant) }}</p><p v-if="app.quote.credits.amount">{{ app.quote.credits.amount }} bonus Credits / {{ app.cadenceLabel(app.quote.credits.cadence) }} · {{ app.quote.credits.validityDays }} days validity.</p></div><button class="mobile-primary" :disabled="app.busy" @click="$emit('purchase')">{{ app.busy?'Processing…':app.quote.action==='change_plan'?'Confirm plan change':app.quote.suit?'Subscribe · '+app.money(app.quote.sku.priceCents,app.quote.sku.currency):'Buy Credits · '+app.money(app.quote.sku.priceCents,app.quote.sku.currency) }}</button><button class="mobile-secondary" :disabled="app.busy" @click="$emit('close')">Cancel</button></template>
  <template v-if="app.serviceQuote"><h2>{{ app.serviceQuote.name }}</h2><p v-if="app.serviceQuote.billingSource==='included'">Included with your membership. One use will be reserved and restored if this request fails. No extra Credits will be charged.</p><p v-else>This request uses {{ app.serviceQuote.credits }} {{ creditTypeLabel(app.serviceQuote.creditType||'LEGACY_CREDIT') }} for one user request. They will be reserved while preparing your result and released if the request fails.</p><button class="mobile-primary" :disabled="app.busy" @click="$emit('service')">{{ app.busy?'Preparing…':app.serviceQuote.billingSource==='included'?'Generate · Included':'Confirm · '+app.serviceQuote.credits+' '+creditTypeLabel(app.serviceQuote.creditType||'LEGACY_CREDIT') }}</button><button class="mobile-secondary" :disabled="app.busy" @click="$emit('close')">Cancel</button></template>
  <template v-if="app.redemptionQuote"><h2>Unlock {{ app.redemptionQuote.name }}</h2><p>{{ app.redemptionQuote.credits }} {{ creditTypeLabel(app.redemptionQuote.creditType||'LEGACY_CREDIT') }} · {{ app.redemptionQuote.validityDays?app.redemptionQuote.validityDays+' days of access':'No expiry' }}</p><p v-if="app.redemptionQuote.contentType==='training_program'">Includes all workouts in this Program when accessed through the Program.</p><p>Membership cancellation does not remove this independent unlock. Replay uses no additional Credits.</p><button class="mobile-primary" :disabled="app.busy" @click="$emit('redeem')">{{ app.busy?'Unlocking…':'Unlock · '+app.redemptionQuote.credits+' '+creditTypeLabel(app.redemptionQuote.creditType||'LEGACY_CREDIT') }}</button><button class="mobile-secondary" :disabled="app.busy" @click="$emit('close')">Cancel</button></template>
  <template v-if="app.renewalTarget"><h2>{{ app.renewalTarget.autoRenew?'Cancel renewal?':'Resume renewal?' }}</h2><p>Your current membership stays active until {{ app.shortDate(app.renewalTarget.grant.expiresAt) }}.</p><p v-if="app.renewalTarget.autoRenew">Your saved results, independent unlocks and extra Credits remain. Any scheduled plan change will also be canceled.</p><button class="mobile-primary" :disabled="app.busy" @click="$emit('renew')">{{ app.renewalTarget.autoRenew?'Confirm cancellation':'Resume renewal' }}</button><button class="mobile-secondary" @click="$emit('close')">Keep current setting</button></template>
  <template v-if="app.notice"><h2>{{ app.notice.title }}</h2><p>{{ app.notice.body }}</p><button class="mobile-primary" @click="$emit('done')">{{ app.returnTo?'Return to '+app.returnTitle:'Done' }}</button></template>
  <template v-if="app.showLedger"><h2>Credit activity</h2><div v-for="entry in app.data.ledger.filter(entry=>!entry.creditType||entry.creditType==='LEGACY_CREDIT')" :key="entry.id" class="mobile-batch"><div><strong>{{ app.eventLabel(entry.type) }}</strong><span>{{ entry.reason }} · {{ app.shortDate(entry.createdAt) }}</span></div><b>{{ entry.amount>0?'+':'' }}{{ entry.amount }}</b></div><p class="mobile-small">Holds are reservations, not extra charges. Included usage is shown separately.</p></template>
  <template v-if="app.program"><h2>{{ app.program.name }}</h2><button v-for="member in app.program.membersPreview" :key="member.id" class="mobile-secondary" @click="$emit('workout',member)">{{ member.name }} →</button></template>
  <p v-if="app.error" class="mobile-error" role="alert">{{ app.error }}</p>
</sf-sheet>
</template>
<script>
import {SfSheet} from '@/design-system'
import {creditTypeLabel,creditGrantLabel} from '@/utils/entitlements'
export default {components:{SfSheet},props:{app:Object},methods:{creditTypeLabel,creditGrantLabel},computed:{gateTitle(){return !this.app.gate?'':this.app.gate.reason==='CONSUMPTION_POLICY_UNDEFINED'?'Not available yet':this.app.gate.reason==='ENTITLEMENT_REQUIRED'?'Feature access':this.app.gate.reason==='INCLUDED_USAGE_EXHAUSTED'?'Included usage used up':this.app.gate.reason==='CREDITS_INSUFFICIENT'?'More Credits to continue':'Service unavailable'},automaticChat(){return this.app.serviceQuote&&this.app.serviceQuote.serviceId==='ai_chat'&&this.app.serviceQuote.billingSource==='included'},visible(){return !!(this.app.gate||this.app.quote||(this.app.serviceQuote&&!this.automaticChat)||this.app.redemptionQuote||this.app.notice||this.app.showLedger||this.app.program||this.app.renewalTarget)}}}
</script>
